bool HMCfgHandler::validate()
{
    bool result{true};
    // number of checkpoints
    uint32_t cp_total{0};
    for (const auto& se : supervised_entities_)
    {
        cp_total += se.checkpoints.size();
    }
    result &= (cp_total_ == cp_total);
    // check every mode config
    for (const auto& p_cfg_mode : cfg_modes_)
    {
        result &= p_cfg_mode->validate();
    }

    return result;
}

bool HMCfgHandler::is_se_contained(const hm_mode_t mode_id,
                                   const hm_supervised_entity_id_t se_id)
{
    bool result{false};
    if ((mode_id >= 0) && (mode_id < cfg_modes_.size()))
    {
        result = cfg_modes_[mode_id]->is_se_contained(se_id);
    }
    return result;
}

bool HMCfgHandler::is_cp_contained(const hm_mode_t mode_id,
                                   const hm_supervised_entity_id_t se_id,
                                   const hm_checkpoint_id_t cp_id)
{
    bool result{false};
    if ((mode_id >= 0) && (mode_id < cfg_modes_.size()))
    {
        result = cfg_modes_[mode_id]->is_cp_contained(se_id, cp_id);
    }
    return result;
}

bool HMCfgHandler::is_hs_contained(const hm_mode_t mode_id,
                                   const hm_external_supervision_id_t es_id)
{
    bool result{false};
    if ((mode_id >= 0) && (mode_id < cfg_modes_.size()))
    {
        result = cfg_modes_[mode_id]->is_hs_contained(es_id);
    }
    return result;
}

const std::vector<std::shared_ptr<const HMCPSupervisionCfgIntf>>&
HMCfgHandler::get_cp_supervisions(const hm_mode_t mode_id, const hm_supervised_entity_id_t se_id)
{
    if ((mode_id >= 0) && (mode_id < cfg_modes_.size()))
    {
        return cfg_modes_[mode_id]->get_cp_supervisions(se_id);
    }
    return empty_cp_supervision_;
}

std::shared_ptr<const HMHSSupervisionCfgIntf>
HMCfgHandler::get_hs_supervision(const hm_mode_t mode_id, const hm_external_supervision_id_t es_id)
{
    if ((mode_id >= 0) && (mode_id < cfg_modes_.size()))
    {
        return cfg_modes_[mode_id]->get_hs_supervision(es_id);
    }
    return nullptr;
}

