bool HMCfgHandler::get_se_type(const hm_supervised_entity_id_t se_id, hm_supervised_entity_type_t& type)
{
    bool result{false};
    const auto found_item_iter = std::find_if(supervised_entities_.begin(), supervised_entities_.end(),
                                              [se_id](const hm_supervised_entity_t& se_type) {
                                                  return (se_type.se_id == se_id); });
    if (found_item_iter != supervised_entities_.end())
    {
        type = (*found_item_iter).type;
        result = true;
    }
    return result;
}

